-- Issue #283 (Kindle mid-term Assembly election): election, voter receipt and anonymous party-list ballot tables, separate from the civic_* presidential tables. The ballot table carries no timestamp and no citizen. Additive tables only.
CREATE TABLE IF NOT EXISTS assembly_elections ( id TEXT PRIMARY KEY, nation_id TEXT NOT NULL CHECK(nation_id='kindle'), policy TEXT NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')), opens_at INTEGER NOT NULL, closes_at INTEGER NOT NULL, closed_at INTEGER, result_json TEXT, CHECK(closes_at=opens_at+259200), CHECK(closed_at IS NULL OR closed_at>=closes_at), CHECK(result_json IS NULL OR closed_at IS NOT NULL) );
CREATE TABLE IF NOT EXISTS assembly_voter_receipts ( election_id TEXT NOT NULL REFERENCES assembly_elections(id), clerk_user_id TEXT NOT NULL REFERENCES citizens(clerk_user_id), district_id TEXT NOT NULL CHECK(district_id IN ('forgehaven','tarrek-foundry','kolt-savanna')), request_id TEXT NOT NULL UNIQUE, checked_at INTEGER NOT NULL, ballot_written INTEGER NOT NULL DEFAULT 0 CHECK(ballot_written IN (0,1)), policy TEXT NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')), PRIMARY KEY(election_id,clerk_user_id) );
CREATE TABLE IF NOT EXISTS assembly_anonymous_ballots ( id TEXT PRIMARY KEY, election_id TEXT NOT NULL REFERENCES assembly_elections(id), district_id TEXT NOT NULL CHECK(district_id IN ('forgehaven','tarrek-foundry','kolt-savanna')), party_id TEXT NOT NULL CHECK(party_id IN ('steady-hand','open-ledger','dockside-builders')), policy TEXT NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')) );
CREATE INDEX IF NOT EXISTS idx_assembly_ballots_election ON assembly_anonymous_ballots(election_id);
